import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import {
  PERIOD_DESCRIPTIONS,
  PERIOD_LABELS,
  getPeriodRange,
  parsePeriod,
  type Period,
} from "../../reports/period";
import { addCapitalMovement } from "./actions";
import CapitalForm from "./capital-form";

type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
type AccountRow = { id: string; code: string; type: string; normal_balance: string };

function formatRupiah(value: number) {
  const sign = value < 0 ? "-" : "";
  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
}

// Total Modal (Modal Pemilik + Laba Ditahan + Laba Berjalan) as of a point in
// time — same 3-part sum Neraca uses, evaluated at an arbitrary cutoff so it
// can be diffed across a period. `strictlyBeforeIso: null` means "since the
// business's inception" (i.e. balance 0, there's nothing before that).
async function totalModalAsOf(
  supabase: SupabaseServerClient,
  businessId: string,
  accounts: AccountRow[],
  strictlyBeforeIso: string | null,
): Promise<number> {
  if (strictlyBeforeIso === null) return 0;

  const { data: entries } = await supabase
    .from("journal_entries")
    .select("journal_lines(debit, credit, account_id)")
    .eq("business_id", businessId)
    .lt("date", strictlyBeforeIso);

  const balanceByAccount = new Map<string, number>();
  for (const entry of entries ?? []) {
    const lines = entry.journal_lines as unknown as {
      debit: number;
      credit: number;
      account_id: string;
    }[];
    for (const l of lines) {
      const cur = balanceByAccount.get(l.account_id) ?? 0;
      balanceByAccount.set(l.account_id, cur + Number(l.debit) - Number(l.credit));
    }
  }

  let modalTotal = 0;
  let pendapatanTotal = 0;
  let bebanTotal = 0;
  for (const a of accounts) {
    const raw = balanceByAccount.get(a.id) ?? 0;
    const balance = a.normal_balance === "debit" ? raw : -raw;
    if (a.type === "modal") modalTotal += balance;
    else if (a.type === "pendapatan") pendapatanTotal += balance;
    else if (a.type === "beban") bebanTotal += balance;
  }
  return modalTotal + pendapatanTotal - bebanTotal;
}

export default async function LaporanPerubahanModalPage({
  params,
  searchParams,
}: {
  params: Promise<{ businessId: string }>;
  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
}) {
  const { businessId } = await params;
  const { period: periodParam, from, to } = await searchParams;
  const period = parsePeriod(periodParam);
  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);

  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const { data: accounts } = await supabase
    .from("accounts")
    .select("id, code, type, normal_balance")
    .eq("business_id", businessId)
    .in("type", ["modal", "pendapatan", "beban"]);

  const accountRows = (accounts ?? []) as AccountRow[];
  const modalPemilikAccount = accountRows.find((a) => a.code === "3-001");

  // "Now" as an upper cutoff for open-ended periods (today/week/month/all).
  const nowIso = new Date().toISOString();
  const modalAkhirCutoff = toIsoExclusive ?? nowIso;

  const [modalAwal, modalAkhir] = await Promise.all([
    totalModalAsOf(supabase, businessId, accountRows, fromIso),
    totalModalAsOf(supabase, businessId, accountRows, modalAkhirCutoff),
  ]);

  let setoran = 0;
  let prive = 0;
  if (modalPemilikAccount) {
    let periodQuery = supabase
      .from("journal_entries")
      .select("journal_lines(debit, credit, account_id)")
      .eq("business_id", businessId);
    if (fromIso) periodQuery = periodQuery.gte("date", fromIso);
    if (toIsoExclusive) periodQuery = periodQuery.lt("date", toIsoExclusive);
    const { data: periodEntries } = await periodQuery;

    for (const entry of periodEntries ?? []) {
      const lines = entry.journal_lines as unknown as {
        debit: number;
        credit: number;
        account_id: string;
      }[];
      for (const l of lines) {
        if (l.account_id !== modalPemilikAccount.id) continue;
        setoran += Number(l.credit);
        prive += Number(l.debit);
      }
    }
  }

  const labaBersihPeriode = modalAkhir - modalAwal - (setoran - prive);

  const boundAddCapital = addCapitalMovement.bind(null, businessId);
  const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });

  return (
    <div className="w-full max-w-2xl">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h1 className="text-lg font-bold text-zinc-900">Perubahan Modal — {business.name}</h1>
          <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
        </div>
        <div className="flex flex-wrap gap-1.5">
          {(["today", "week", "month", "all", "custom"] as Period[]).map((p) => (
            <Link
              key={p}
              href={`/business/${businessId}/accounting/modal?period=${p}`}
              className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
                p === period
                  ? "bg-brand-600 text-white"
                  : "bg-white text-zinc-600 hover:bg-zinc-100"
              }`}
            >
              {PERIOD_LABELS[p]}
            </Link>
          ))}
        </div>
      </div>

      {period === "custom" && (
        <form
          method="get"
          className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
        >
          <input type="hidden" name="period" value="custom" />
          <label className="text-xs font-medium text-zinc-600">
            Dari
            <input
              type="date"
              name="from"
              defaultValue={from}
              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
            />
          </label>
          <label className="text-xs font-medium text-zinc-600">
            Sampai
            <input
              type="date"
              name="to"
              defaultValue={to}
              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
            />
          </label>
          <button
            type="submit"
            className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
          >
            Terapkan
          </button>
        </form>
      )}

      <div className="mt-6 overflow-hidden rounded-2xl border border-zinc-200 bg-white">
        <div className="space-y-2.5 p-5 text-sm">
          <div className="flex items-center justify-between">
            <span className="text-zinc-600">Modal Awal</span>
            <span className="font-semibold text-zinc-900">{formatRupiah(modalAwal)}</span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-zinc-600">+ Setoran Modal</span>
            <span className="font-semibold text-brand-700">{formatRupiah(setoran)}</span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-zinc-600">− Prive (Penarikan Pribadi)</span>
            <span className="font-semibold text-red-500">
              {prive > 0 ? `−${formatRupiah(prive)}` : formatRupiah(0)}
            </span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-zinc-600">
              {labaBersihPeriode >= 0 ? "+ Laba Bersih Periode Ini" : "− Rugi Bersih Periode Ini"}
            </span>
            <span
              className={`font-semibold ${labaBersihPeriode >= 0 ? "text-brand-700" : "text-red-500"}`}
            >
              {formatRupiah(labaBersihPeriode)}
            </span>
          </div>
          <div className="flex items-center justify-between border-t border-zinc-100 pt-3 text-base font-bold text-zinc-900">
            <span>Modal Akhir</span>
            <span>{formatRupiah(modalAkhir)}</span>
          </div>
        </div>
      </div>

      <div className="mt-4 rounded-2xl border border-zinc-200 bg-white p-5">
        <h2 className="mb-4 text-sm font-semibold text-zinc-900">Catat Setoran / Prive</h2>
        <CapitalForm action={boundAddCapital} today={today} />
      </div>

      <p className="mt-3 text-center text-[11px] text-zinc-400">
        "Laba Bersih Periode Ini" dihitung dari selisih Total Modal awal dan akhir periode,
        dikurangi setoran/prive — jadi tetap akurat walau ada{" "}
        <Link href={`/business/${businessId}/accounting/tutup-buku`} className="text-brand-600 hover:underline">
          Tutup Buku
        </Link>{" "}
        di tengah periode.
      </p>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

const TYPE_LABELS: Record<string, string> = {
  aset: "Aset",
  kewajiban: "Kewajiban",
  modal: "Modal",
};

function formatRupiah(value: number) {
  const sign = value < 0 ? "-" : "";
  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
}

export default async function NeracaPage({
  params,
  searchParams,
}: {
  params: Promise<{ businessId: string }>;
  searchParams: Promise<{ date?: string }>;
}) {
  const { businessId } = await params;
  const { date } = await searchParams;
  const asOfDate = /^\d{4}-\d{2}-\d{2}$/.test(date ?? "") ? (date as string) : new Date().toISOString().slice(0, 10);
  const asOfIso = `${asOfDate}T23:59:59+07:00`;

  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const { data: accounts } = await supabase
    .from("accounts")
    .select("id, code, name, type, normal_balance")
    .eq("business_id", businessId)
    .order("code", { ascending: true });

  const { data: entries } = await supabase
    .from("journal_entries")
    .select("journal_lines(debit, credit, account_id)")
    .eq("business_id", businessId)
    .lte("date", asOfIso);

  const balanceByAccount = new Map<string, number>();
  for (const entry of entries ?? []) {
    const lines = entry.journal_lines as unknown as {
      debit: number;
      credit: number;
      account_id: string;
    }[];
    for (const l of lines) {
      const cur = balanceByAccount.get(l.account_id) ?? 0;
      balanceByAccount.set(l.account_id, cur + Number(l.debit) - Number(l.credit));
    }
  }

  function balanceOf(a: { id: string; normal_balance: string }) {
    const raw = balanceByAccount.get(a.id) ?? 0;
    return a.normal_balance === "debit" ? raw : -raw;
  }

  const asetRows = (accounts ?? []).filter((a) => a.type === "aset").map((a) => ({ ...a, balance: balanceOf(a) }));
  const kewajibanRows = (accounts ?? []).filter((a) => a.type === "kewajiban").map((a) => ({ ...a, balance: balanceOf(a) }));
  const modalRows = (accounts ?? []).filter((a) => a.type === "modal").map((a) => ({ ...a, balance: balanceOf(a) }));
  const pendapatanRows = (accounts ?? []).filter((a) => a.type === "pendapatan").map((a) => ({ ...a, balance: balanceOf(a) }));
  const bebanRows = (accounts ?? []).filter((a) => a.type === "beban").map((a) => ({ ...a, balance: balanceOf(a) }));

  const totalAset = asetRows.reduce((s, a) => s + a.balance, 0);
  const totalKewajiban = kewajibanRows.reduce((s, a) => s + a.balance, 0);
  const totalModalRecorded = modalRows.reduce((s, a) => s + a.balance, 0);
  const totalPendapatan = pendapatanRows.reduce((s, a) => s + a.balance, 0);
  const totalBeban = bebanRows.reduce((s, a) => s + a.balance, 0);
  const labaBerjalan = totalPendapatan - totalBeban;
  const totalModal = totalModalRecorded + labaBerjalan;
  const selisih = totalAset - (totalKewajiban + totalModal);

  return (
    <div className="w-full max-w-2xl">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h1 className="text-lg font-bold text-zinc-900">Neraca — {business.name}</h1>
          <p className="mt-0.5 text-xs text-zinc-500">Per tanggal {asOfDate}</p>
        </div>
        <form method="get" className="flex items-center gap-2">
          <input
            type="date"
            name="date"
            defaultValue={asOfDate}
            className="rounded-lg border border-zinc-200 px-2.5 py-1.5 text-xs"
          />
          <button
            type="submit"
            className="rounded-lg bg-brand-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-700"
          >
            Tampilkan
          </button>
        </form>
      </div>

      <div className="mt-6 grid gap-4 sm:grid-cols-2">
        <div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white">
          <div className="border-b border-zinc-100 px-4 py-3">
            <h2 className="text-sm font-bold text-zinc-900">{TYPE_LABELS.aset}</h2>
          </div>
          <div className="divide-y divide-zinc-50 px-4">
            {asetRows.map((a) => (
              <div key={a.id} className="flex items-center justify-between py-2 text-xs">
                <span className="text-zinc-600">{a.name}</span>
                <span className="font-medium text-zinc-800">{formatRupiah(a.balance)}</span>
              </div>
            ))}
          </div>
          <div className="flex items-center justify-between border-t border-zinc-100 px-4 py-3 text-sm font-bold text-zinc-900">
            <span>Total Aset</span>
            <span>{formatRupiah(totalAset)}</span>
          </div>
        </div>

        <div className="space-y-4">
          <div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white">
            <div className="border-b border-zinc-100 px-4 py-3">
              <h2 className="text-sm font-bold text-zinc-900">{TYPE_LABELS.kewajiban}</h2>
            </div>
            <div className="divide-y divide-zinc-50 px-4">
              {kewajibanRows.map((a) => (
                <div key={a.id} className="flex items-center justify-between py-2 text-xs">
                  <span className="text-zinc-600">{a.name}</span>
                  <span className="font-medium text-zinc-800">{formatRupiah(a.balance)}</span>
                </div>
              ))}
            </div>
            <div className="flex items-center justify-between border-t border-zinc-100 px-4 py-3 text-sm font-bold text-zinc-900">
              <span>Total Kewajiban</span>
              <span>{formatRupiah(totalKewajiban)}</span>
            </div>
          </div>

          <div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white">
            <div className="border-b border-zinc-100 px-4 py-3">
              <h2 className="text-sm font-bold text-zinc-900">{TYPE_LABELS.modal}</h2>
            </div>
            <div className="divide-y divide-zinc-50 px-4">
              {modalRows.map((a) => (
                <div key={a.id} className="flex items-center justify-between py-2 text-xs">
                  <span className="text-zinc-600">{a.name}</span>
                  <span className="font-medium text-zinc-800">{formatRupiah(a.balance)}</span>
                </div>
              ))}
              <div className="flex items-center justify-between py-2 text-xs">
                <span className="text-zinc-600">Laba Berjalan (belum ditutup)</span>
                <span className="font-medium text-zinc-800">{formatRupiah(labaBerjalan)}</span>
              </div>
            </div>
            <div className="flex items-center justify-between border-t border-zinc-100 px-4 py-3 text-sm font-bold text-zinc-900">
              <span>Total Modal</span>
              <span>{formatRupiah(totalModal)}</span>
            </div>
          </div>
        </div>
      </div>

      <div
        className={`mt-4 rounded-2xl border p-4 text-center text-sm font-semibold ${
          Math.abs(selisih) < 1
            ? "border-brand-200 bg-brand-50 text-brand-700"
            : "border-red-200 bg-red-50 text-red-600"
        }`}
      >
        {Math.abs(selisih) < 1
          ? "✓ Aset = Kewajiban + Modal (seimbang)"
          : `⚠ Selisih ${formatRupiah(selisih)} — periksa jurnal manual yang mungkin belum seimbang`}
      </div>

      <p className="mt-3 text-center text-[11px] text-zinc-400">
        "Laba Berjalan" adalah pendapatan dikurangi beban sejak tutup buku terakhir (atau sejak
        awal pencatatan kalau belum pernah tutup buku) sampai tanggal ini. Kunci periode yang
        sudah selesai lewat{" "}
        <Link href={`/business/${businessId}/accounting/tutup-buku`} className="text-brand-600 hover:underline">
          Tutup Buku
        </Link>
        .
      </p>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { addTransfer } from "./actions";
import TransferForm from "./transfer-form";

export default async function TransferKasPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const { data: accounts } = await supabase
    .from("accounts")
    .select("code, name")
    .eq("business_id", businessId)
    .eq("type", "aset")
    .order("code", { ascending: true });

  const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });
  const boundAddTransfer = addTransfer.bind(null, businessId);
  const onlyOneAccount = (accounts ?? []).length < 2;

  return (
    <div className="w-full max-w-2xl">
      <h1 className="text-lg font-bold text-zinc-900">Transfer Kas/Bank — {business.name}</h1>
      <p className="mt-0.5 text-xs text-zinc-500">
        Catat perpindahan uang antar akun kas &amp; bank (mis. setor tunai ke rekening, tarik tunai
        dari ATM).
      </p>

      {onlyOneAccount ? (
        <div className="mt-6 rounded-2xl border border-dashed border-zinc-200 bg-white p-6 text-center">
          <p className="text-sm text-zinc-500">
            Baru ada satu akun kas/bank ("Kas & Bank"). Tambahkan rekening lain dulu (mis. "Bank
            BCA") lewat{" "}
            <Link href={`/business/${businessId}/accounting/daftar-akun`} className="text-brand-600 hover:underline">
              Daftar Akun
            </Link>{" "}
            (jenis Aset) supaya bisa dipakai di sini.
          </p>
        </div>
      ) : (
        <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
          <h2 className="mb-4 text-sm font-semibold text-zinc-900">Catat Transfer</h2>
          <TransferForm action={boundAddTransfer} today={today} accounts={accounts ?? []} />
        </div>
      )}

      <p className="mt-3 text-center text-[11px] text-zinc-400">
        Penjualan, pengeluaran, pembelian, payroll, dan piutang selalu memposting otomatis ke "Kas
        &amp; Bank" (1-001) — akun kas/bank tambahan cuma dipakai untuk transfer manual seperti ini.
        Riwayat transfer bisa dilihat di{" "}
        <Link href={`/business/${businessId}/accounting/jurnal`} className="text-brand-600 hover:underline">
          Jurnal Transaksi
        </Link>
        .
      </p>
    </div>
  );
}

