"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";

export type JournalState = { error: string | null };

type LineInput = { account_code: string; debit: number; credit: number };

export async function addJournalEntry(
  businessId: string,
  _prevState: JournalState,
  formData: FormData,
): Promise<JournalState> {
  const date = formData.get("date") as string;
  const description = (formData.get("description") as string)?.trim();
  const linesRaw = formData.get("lines") as string;

  if (!date) {
    return { error: "Tanggal wajib diisi." };
  }
  if (!description) {
    return { error: "Keterangan wajib diisi." };
  }

  let lines: LineInput[];
  try {
    lines = JSON.parse(linesRaw);
  } catch {
    return { error: "Baris jurnal tidak valid." };
  }

  const validLines = lines.filter(
    (l) => l.account_code && (Number(l.debit) > 0 || Number(l.credit) > 0),
  );

  if (validLines.length < 2) {
    return { error: "Minimal 2 baris (debit dan kredit) harus diisi." };
  }

  const totalDebit = validLines.reduce((s, l) => s + Number(l.debit), 0);
  const totalCredit = validLines.reduce((s, l) => s + Number(l.credit), 0);

  if (Math.round(totalDebit * 100) !== Math.round(totalCredit * 100)) {
    return {
      error: `Jurnal belum seimbang: debit ${totalDebit.toLocaleString("id-ID")} ≠ kredit ${totalCredit.toLocaleString("id-ID")}.`,
    };
  }

  const supabase = await createClient();
  const { error } = await supabase.rpc("post_journal_entry", {
    p_business_id: businessId,
    p_date: date,
    p_description: description,
    p_lines: validLines,
  });

  if (error) {
    return { error: error.message };
  }

  revalidatePath(`/business/${businessId}/accounting/jurnal`);
  return { error: null };
}

"use client";

import { useActionState, useRef, useState, useEffect } from "react";
import type { AddPurchaseState } from "./actions";

const initialState: AddPurchaseState = { error: null };

type SupplierOption = { id: string; name: string };
type IngredientOption = { id: string; name: string; unit: string; stock: number };
type ProductOption = { id: string; name: string; stock: number };

export default function AddPurchaseForm({
  action,
  today,
  isFnb,
  suppliers,
  ingredients,
  products,
}: {
  action: (state: AddPurchaseState, formData: FormData) => Promise<AddPurchaseState>;
  today: string;
  isFnb: boolean;
  suppliers: SupplierOption[];
  ingredients: IngredientOption[];
  products: ProductOption[];
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);
  const [category, setCategory] = useState(isFnb ? "Bahan Baku" : "Barang Dagang");
  const [ingredientId, setIngredientId] = useState(ingredients[0]?.id ?? "");
  const [amount, setAmount] = useState("");
  const [paymentMode, setPaymentMode] = useState<"lunas" | "utang" | "sebagian">("lunas");
  const [paidAmount, setPaidAmount] = useState("");

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
      setPaymentMode("lunas");
      setPaidAmount("");
      setAmount("");
    }
  }, [pending, state.error]);

  const isIngredientPurchase = category === "Bahan Baku";
  const selectedIngredient = ingredients.find((i) => i.id === ingredientId);

  const effectivePaidAmount =
    paymentMode === "lunas" ? amount : paymentMode === "utang" ? "0" : paidAmount;

  return (
    <form ref={formRef} action={formAction} className="space-y-3">
      <div className="grid grid-cols-2 gap-2.5">
        <div>
          <label htmlFor="date" className="mb-1 block text-xs font-medium text-zinc-600">
            Tanggal
          </label>
          <input
            id="date"
            name="date"
            type="date"
            defaultValue={today}
            required
            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          />
        </div>
        <div>
          <label htmlFor="supplierId" className="mb-1 block text-xs font-medium text-zinc-600">
            Supplier (opsional)
          </label>
          <select
            id="supplierId"
            name="supplierId"
            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          >
            <option value="">— Tanpa supplier —</option>
            {suppliers.map((s) => (
              <option key={s.id} value={s.id}>
                {s.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {isFnb && (
        <div>
          <label htmlFor="category" className="mb-1 block text-xs font-medium text-zinc-600">
            Kategori
          </label>
          <select
            id="category"
            name="category"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          >
            <option value="Bahan Baku">Bahan Baku</option>
            <option value="Barang Dagang">Barang Dagang</option>
          </select>
        </div>
      )}
      {!isFnb && <input type="hidden" name="category" value="Barang Dagang" />}

      {isIngredientPurchase ? (
        <div className="space-y-2 rounded-xl bg-amber-50 p-3">
          <div>
            <label htmlFor="ingredientId" className="mb-1 block text-xs font-medium text-amber-800">
              Bahan yang Dibeli
            </label>
            <select
              id="ingredientId"
              name="ingredientId"
              value={ingredientId}
              onChange={(e) => setIngredientId(e.target.value)}
              className="w-full rounded-xl border border-amber-200 bg-white px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
            >
              {ingredients.length === 0 && <option value="">Belum ada bahan baku</option>}
              {ingredients.map((i) => (
                <option key={i.id} value={i.id}>
                  {i.name} (stok: {i.stock} {i.unit})
                </option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-2.5">
            <div>
              <label htmlFor="qty" className="mb-1 block text-xs font-medium text-amber-800">
